def standardize_time(time):
    time = re.sub(r'[_-]', '', time)
    time = re.sub(r'\s+', ':', time)
    hours, minutes = time.split(':')
    return "%s" % ({hours}:{minutes})

def calculate_average_delay(data):
    sched_dep_time = [standardize_time(row['sched_dep_time']) for row in data]
    actual_time = [row['actual_time'] for row in data]
    delays = [int(act - std) for act, std in zip(actual_time, sched_dep_time)]
    return sum(delays) / len(delays)

data = [{"sched_dep_time": "__7:53_A.M.__", "actual_time": "10:28 A.M."}, ...]
print(calculate_average_delay(data))

